1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
4	  sword: 100,
5	  amulet: 60,
6	  staff: 80,
7	  potion: 40,
8	  rune: 25,
9	};
10	
11	type Item = {
12	  type: string;
13	  material?: string;
14	  enchantmentLevel?: number;
15	  cursed?: boolean;
16	};
17	
18	type Step = {
19	  op: string;
20	  items: Item[];
21	};
22	
23	type Scenario = {
24	  customer: { yearsWithMHPCO: number };
25	  steps: Step[];
26	};
27	
28	type QuoteResult = {
29	  premium: number;
30	};
31	
32	type ScenarioOutput = {
33	  results: QuoteResult[];
34	};
35	
36	const premiumForItem = (item: Item): number => {
37	  const basePremium = BASE_PREMIUM_BY_ITEM_TYPE[item.type];
38	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
39	  return basePremium + firstInsuranceSurcharge;
40	};
41	
42	const premiumForItems = (items: Item[]): number =>
43	  items.reduce((total, item) => total + premiumForItem(item), 0);
44	
45	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
46	  results: scenario.steps.map((step) => ({
47	    premium: Math.ceil(premiumForItems(step.items) + PROCESSING_FEE),
48	  })),
49	});
